        private static readonly Dictionary<ushort, RazerDirectRow> s_byProductId = Index();

        private static Dictionary<ushort, RazerDirectRow> Index()
        {
            var index = new Dictionary<ushort, RazerDirectRow>(Rows.Length);
            foreach (var row in Rows) index[row.ProductId] = row;
            return index;
        }

        internal static RazerDirectRow Find(ushort productId)
            => s_byProductId.TryGetValue(productId, out var row) ? row : null;
    }
